            len = pors_binom_r23_offsets[row + 1u] - off;
            pors_u256_load_limbs(out, pors_binom_r23_data + off, len);
            break;
        case 24u:
            row = block - 24u;
            off = pors_binom_r24_offsets[row];
            len = pors_binom_r24_offsets[row + 1u] - off;
